cd /tmp/sv-3e1944276cf24e058cc24372dacfe148/advanced-multi-complexity && python3 -c "
import json
baseline = json.load(open('baseline-packages.json'))
after = json.load(open('after-cpm-packages.json'))

def get_packages(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            key = f\"{name} ({fw['framework']})\"
            for pkg in fw.get('topLevelPackages', []):
                result.setdefault(key, {})[pkg['id']] = pkg['resolvedVersion']
    return result

b = get_packages(baseline)
a = get_packages(after)

changes = []
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(pkg, 'N/A')
        av = ap.get(pkg, 'N/A')
        if bv != av:
            changes.append((proj, pkg, bv, av))

if changes:
    print('CHANGES:')
    for c in changes:
        print(f'  {c[0]}: {c[1]} {c[2]} -> {c[3]}')
else:
    print('No version changes detected (all packages resolve identically)')
"

